name: 🚀 Safe App Deploy Check + Slack Notify

on: push: branches: [main] pull_request: branches: [main]

jobs: validate-safe-app: runs-on: ubuntu-latest

steps:
  - name: 📅 Checkout repo
    uses: actions/checkout@v3

  - name: 🧪 Validate safedata.json structure
    run: |
      jq '.' app.safe.global/safedata.json > /dev/null || {
        echo "Invalid JSON in safedata.json";
        exit 1;
      }

  - name: 🔍 Check required fields
    run: |
      for field in name description iconPath url network version appUrl; do
        if ! jq -e ".${field}" app.safe.global/safedata.json > /dev/null; then
          echo "Missing field: $field";
          exit 1;
        fi
      done

  - name: 🌐 Check appUrl is reachable
    run: |
      APP_URL=$(jq -r .appUrl app.safe.global/safedata.json)
      echo "Checking $APP_URL ..."
      curl --fail --silent --head "$APP_URL" || {
        echo "App URL is not reachable: $APP_URL"
        exit 1
      }

  - name: 🎉 Format safedata.json with Prettier
    run: |
      npm install --global prettier
      prettier --check app.safe.global/safedata.json || {
        echo "Prettier check failed. Run 'prettier --write app.safe.global/safedata.json'";
        exit 1;
      }

  - name: 📣 Notify Slack
    if: always()
    run: |
      STATUS="${{ job.status }}"
      COLOR="#36a64f"
      if [[ "$STATUS" != "success" ]]; then COLOR="#ff0000"; fi

      curl -X POST "$SLACK_WEBHOOK_URL" \
        -H 'Content-type: application/json' \
        -d "{
          \"attachments\": [{
            \"color\": \"$COLOR\",
            \"title\": \"Safe App Deploy Check\",
            \"text\": \"Status: *$STATUS* on \\`$GITHUB_REPOSITORY\\`\\n🔗 https://github.com/$GITHUB_REPOSITORY/actions/runs/$GITHUB_RUN_ID\",
            \"footer\": \"SafeBot 🤖\"
          }]
        }"
    env:
      SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK_URL }}

  - name: ✅ All checks passed
    if: success()
    run: echo "Safe App is good to go! 🎉"
